"""Données rédactionnelles propres aux dix scénarios B du LOT226."""
SCENARIOS = {
1: dict(
 refs=['S21','S35','S02','S17','S24','S28'],
 focus='Le scénario étudie la souffrance dépressive ou anxieuse qui complique la vie avec une maladie chronique. Il ne confond pas une réaction compréhensible, un épisode dépressif et une anxiété dont la cause somatique reste à examiner.',
 case='Une femme de 59 ans, suivie pour une maladie cardiaque, ne sort plus et abandonne des activités qu’elle appréciait. Elle dit que ses médicaments ne servent plus à rien et que sa famille serait mieux sans elle. Sa fatigue peut relever de plusieurs causes; le propos sur la mort change immédiatement la priorité.',
 epi='La recommandation suisse sur les troubles dépressifs unipolaires a été mise à jour en 2025 et remplace celle de 2016. Elle ne fournit pas une fréquence unique de ce scénario chez tous les malades chroniques. L’âge, le sexe et la maladie somatique ne permettent donc pas d’attribuer ici un pourcentage individuel.',
 mechanism=[('La maladie et les pertes fonctionnelles peuvent déclencher une détresse.','Le clinicien décrit les activités abandonnées et les ressources disponibles.','Une prise en charge intégrée traite la maladie et restaure une participation choisie.'),('La perte d’intérêt et le retrait réduisent les occasions d’activité gratifiante.','L’entretien compare le fonctionnement actuel et antérieur sans réduire la fatigue à l’humeur.','Le plan associe un soutien psychothérapeutique adapté et des objectifs fonctionnels réalisables.'),('La charge du traitement peut dépasser les ressources de la personne.','La revue des prises et de leur compréhension recherche une difficulté modifiable.','La décision partagée simplifie le parcours et coordonne les prescripteurs.')],
 diff=[('Un danger suicidaire doit être évalué en premier.','Le médecin demande les idées, le projet, les moyens accessibles et les actes récents.','Le propos actuel et les capacités de sécurité déterminent le besoin d’un relais immédiat.','Une absence de plan déclaré ne garantit pas l’absence de danger.'),('Une décompensation somatique peut expliquer ou aggraver les plaintes.','L’examen et le bilan sont orientés par les symptômes et la maladie connue.','Une aggravation physique aiguë exige son propre parcours urgent.','Une dépression déjà diagnostiquée ne rend pas toute dyspnée psychogène.'),('Une bipolarité ou des symptômes psychotiques modifient la qualification.','L’entretien recherche les épisodes d’activation antérieurs et les perceptions ou convictions inhabituelles.','Un avis psychiatrique clarifie le diagnostic et le traitement.','Un questionnaire dépressif ne distingue pas à lui seul toutes ces situations.'),('Une détresse liée au contexte peut exister sans épisode dépressif établi.','Le clinicien examine durée, intensité, regroupement des symptômes et fonctionnement.','Le soutien et le suivi répondent au besoin même si un diagnostic reste incertain.','L’absence de diagnostic catégoriel ne signifie pas absence de souffrance.')],
 ask=[('Qu’est-ce qui a changé dans vos journées et vos activités?','La comparaison décrit le retentissement et les pertes fonctionnelles.','Le médecin distingue incapacité physique, manque d’intérêt et obstacle matériel.'),('Avez-vous pensé à mourir ou à vous faire du mal?','Une question directe précise un danger que le contexte chronique ne doit pas banaliser.','Le médecin poursuit l’évaluation clinique et organise le niveau de sécurité approprié.'),('Avez-vous connu des périodes d’énergie ou d’activité inhabituellement élevées?','Les épisodes antérieurs peuvent modifier le diagnostic et le choix thérapeutique.','Le médecin documente la chronologie et sollicite un avis spécialisé si nécessaire.'),('Quels médicaments, produits ou substances prenez-vous réellement?','Les effets, interruptions et interactions peuvent contribuer à la situation.','Le médecin confronte les informations aux prescriptions et aux données professionnelles avant toute modification.')],
 exam=[('L’entretien est cohérent et la personne peut décrire ses choix.','Le médecin observe discours, attention, contact et compréhension au cours d’un échange adapté.','Une désorganisation ou une fluctuation récente justifie une évaluation clinique supplémentaire.'),('Le fonctionnement de base correspond à l’état habituel connu.','Le médecin recherche, selon les plaintes, les signes de décompensation de la maladie somatique.','Une anomalie nouvelle n’est pas attribuée automatiquement à l’anxiété.'),('La personne peut envisager un plan de sécurité concret.','Le médecin explore les appuis accessibles et la capacité réelle à utiliser le relais convenu.','Un accord verbal de principe ne remplace pas l’évaluation du danger ni un relais nécessaire.')],
 syndromes=[('Le profil affectif associe humeur, intérêt et fonctionnement.','La personne peut décrire tristesse, perte d’intérêt, fatigue et retrait.','L’examen décrit ralentissement ou agitation éventuels dans leur contexte; aucun signe isolé ne suffit.','La convergence de plusieurs domaines oriente la qualification et le degré de sévérité.'),('Le profil anxieux ou de crise impose de garder le diagnostic ouvert.','La personne décrit inquiétude, peur, manifestations corporelles et circonstances.','Le médecin examine le retentissement physique et recherche une cause aiguë selon les symptômes.','L’émotion et la maladie somatique peuvent coexister sans que l’une annule l’autre.')],
 criteria='Le tableau CIM-11 de la recommandation suisse2025 retient au moins cinq symptômes, dont au moins un du groupe affectif, avec une appréciation de l’intensité et du fonctionnement. La fiche OMS2026 précise une présence la majeure partie de la journée, presque chaque jour, pendant au moins deux semaines; les exclusions et l’histoire restent nécessaires à l’évaluation diagnostique complète; le présent scénario ne reconstruit pas un questionnaire officiel ni des critères anxieux non lus. Une plainte ou un score isolé ne suffit pas.',
 tests=[('L’entretien clinique répond à la question diagnostique.','Le médecin précise les symptômes, leur évolution, les antécédents et les comorbidités.','Une convergence clinique soutient une hypothèse; une discordance impose de la reprendre.','Le diagnostic guide le niveau de soins et reste distinct du score.'),('Un instrument validé peut documenter l’évolution.','Le médecin utilise un formulaire réellement consulté, dans une langue comprise.','Un score élevé signale une charge symptomatique; il ne prédit pas seul le comportement futur.','Les seuils d’un formulaire non lu restent à vérifier et ne sont pas inventés.'),('Le bilan somatique répond à une hypothèse précise.','Le médecin choisit les analyses ou examens selon l’histoire, l’examen et les traitements.','Un résultat normal n’exclut pas toutes les causes de fatigue ni la souffrance psychique.','Une valeur anormale demande une interprétation dans son contexte et une action dédiée.'),('L’évaluation spécialisée clarifie une complexité persistante.','Le médecin transmet les constats, la chronologie et les questions diagnostiques.','L’absence d’amélioration, une forme sévère ou une incertitude importante justifient de réexaminer le plan.','Le relais n’interrompt pas le suivi somatique et social.')],
 urgent=['Le clinicien interrompt l’entretien de routine et évalue immédiatement la nature actuelle du danger. Il clarifie ce qui a été fait, ce qui est envisagé, les moyens disponibles et l’état somatique.','Si le danger ne permet pas un maintien sûr dans le cadre actuel, il organise une évaluation psychiatrique urgente et assure la continuité de surveillance adaptée jusqu’au relais. Il n’attend pas le résultat d’un questionnaire.','La transmission indique les propos et actes constatés, les substances, les traitements, les comorbidités et les ressources réellement disponibles. Un soutien familial ne doit pas être présumé.','Après l’évaluation urgente, le relais distingue la sécurité immédiate, la stratégie thérapeutique et le prochain contact identifié. Une promesse de ne rien faire ne remplace pas cette organisation.'],
 care=[('Le but immédiat est de sécuriser la situation.','Le médecin traite le danger avant les objectifs de participation et coordonne les soins physiques et psychiques.','La réussite exige un relais effectivement obtenu lorsque le cadre actuel ne suffit pas.'),('Le but thérapeutique associe symptômes et fonctionnement.','Le plan dépend de la sévérité, des préférences et de l’histoire; il peut associer psychothérapie et traitement médicamenteux indiqué.','Une baisse de score ne suffit pas si la personne reste incapable d’accéder à ses soins.'),('Le soutien à l’autogestion rend le plan réalisable.','Le médecin choisit avec la personne une action accessible et identifie les obstacles matériels ou relationnels.','Un échec de réalisation conduit à revoir l’obstacle avant d’accuser la motivation.'),('La revue médicamenteuse respecte une limite explicite.','Le scénario ne fournit aucune dose ni spécialité sans lecture de la fiche AIPS applicable.','La dose, la durée, les adaptations rénale ou hépatique et les interactions restent à vérifier avant prescription.')],
 follow=[('La sécurité est réévaluée selon l’état et toute modification clinique.','Le médecin reprend idées de mort, fonctionnement et accès au relais.','Une aggravation impose de réviser immédiatement le niveau de soins.'),('Le bénéfice est jugé sur des objectifs convenus.','La personne et le médecin comparent symptômes, activités et réalisation du plan.','Une amélioration partielle ne justifie pas l’abandon du suivi somatique.'),('La tolérance et la continuité sont vérifiées.','Le médecin recherche activement effets indésirables, interruptions et obstacles.','Toute modification de traitement exige les données professionnelles et un responsable identifié.')],
 pitfalls=[('Un patient anxieux présente une dyspnée nouvelle.','Le médecin recherche une décompensation somatique avant de conclure à une crise anxieuse.','L’étiquette psychiatrique ne neutralise pas le diagnostic différentiel.'),('La personne affirme comprendre mais ne va pas aux rendez-vous.','Le médecin explore aussi coût, transport et charge du parcours.','L’adhésion ne se déduit pas de la seule volonté.'),('La famille demande une décision à la place du patient déprimé.','Le médecin apprécie le discernement pour la décision précise et recherche le consentement.','Un diagnostic dépressif ne vaut pas incapacité automatique.')]
),
2: dict(
 refs=['S04','S20','S26','S33','S02'],
 focus='Le renoncement financier désigne ici une prestation jugée nécessaire mais non reçue pour une raison de coût. La précarité couvre une situation plus large de ressources et de contraintes; ni le revenu isolé ni le montant d’une facture ne suffisent à décrire l’accès réel aux soins.',
 case='Un homme de 62 ans reporte une consultation de suivi et économise ses traitements parce qu’il craint la facture. Il paie une prime mais ne sait pas distinguer franchise et quote-part. Il a reçu un courrier cantonal qu’il ne comprend pas et hésite à demander de l’aide.',
 epi='L’indicateur MonAM consulté rapporte5,5 % de renoncement médical ou dentaire nécessaire pour raisons financières en 2024 chez les personnes de16 ans et plus. La population, la période et le regroupement médical/dentaire doivent rester attachés au chiffre; ce n’est pas la fréquence du scénario chez tous les patients chroniques.',
 mechanism=[('Le reste à charge anticipé peut retarder une prestation nécessaire.','L’entretien identifie le soin reporté et la somme réellement en cause.','Le plan sécurise le soin prioritaire et examine les possibilités de couverture.'),('La maladie peut réduire le revenu ou augmenter la charge administrative.','Le bilan social décrit les changements récents et les prestations disponibles.','L’aide cible la démarche précise et son interlocuteur compétent.'),('Une information incomprise peut rendre une aide théorique inaccessible.','La personne reformule la prochaine étape et montre le document utile si elle l’accepte.','Un accompagnement pratique complète l’information sur les droits.')],
 diff=[('Une décompensation liée à des soins interrompus est prioritaire.','Le médecin évalue les symptômes et les prises effectivement interrompues.','Le soin urgent suit son indication clinique avant la résolution complète du dossier financier.','Une difficulté de paiement ne rend pas une urgence moins grave.'),('Un refus informé peut être distinct d’un renoncement imposé.','Le médecin demande ce que la personne choisirait si l’obstacle financier était levé.','Il distingue préférence personnelle et impossibilité matérielle.','Un refus exprimé sous contrainte de coût ne décrit pas toujours un choix libre.'),('Une incompréhension du décompte peut majorer le coût perçu.','Le service compétent distingue prime, franchise, quote-part et prestation exclue.','Le plan corrige le malentendu puis vérifie l’accès effectif.','Le médecin ne promet pas un remboursement sans qualification de la prestation.'),('Une autre difficulté peut empêcher le soin malgré une aide financière.','L’entretien recherche transport, garde, langue et délais de rendez-vous.','Le plan corrige les obstacles cumulés.','Un subside accordé ne prouve pas qu’un rendez-vous a été obtenu.')],
 ask=[('Quels soins avez-vous reportés et pour quelle raison concrète?','Le type et la date du report permettent d’apprécier le risque clinique.','Le médecin hiérarchise les conséquences et vérifie l’urgence.'),('Quel montant craignez-vous de devoir payer?','La réponse distingue un coût documenté d’une anticipation ou d’une confusion.','Le décompte est repris avec l’accord de la personne et l’interlocuteur compétent.'),('Votre situation de revenu ou de famille a-t-elle récemment changé?','La procédure de réduction des primes tient compte de la situation actuelle selon les règles cantonales.','La personne est orientée vers l’autorité de son canton sans promesse de montant.'),('Qui peut vous aider à faire la démarche et à comprendre la réponse?','Une aide disponible change la faisabilité administrative.','Le plan attribue une tâche, un contact et une vérification de résultat.')],
 exam=[('L’état clinique est stable par rapport à la référence connue.','Le médecin recherche les conséquences des soins ou traitements manqués selon la maladie.','Une aggravation clinique impose son propre parcours sans attendre un calcul financier.'),('Les fonctions de communication permettent un échange fiable.','Le médecin demande une reformulation et adapte la langue ou le support si nécessaire.','Une réponse incomplète conduit à simplifier et à vérifier; elle ne prouve pas une incapacité.'),('Les besoins essentiels sont couverts dans le lieu de vie.','L’entretien décrit alimentation, logement et accès aux moyens de soin sans les présumer.','Une rupture de besoins essentiels justifie une coordination sociale plus urgente.')],
 syndromes=[('Le profil de renoncement reste centré sur une prestation nécessaire.','La personne décrit ce qu’elle n’a pas reçu et le rôle du coût.','L’examen recherche le retentissement de ce report; aucun signe physique ne confirme à lui seul la précarité.','La décision relie gravité du besoin et solution d’accès.'),('Le profil de vulnérabilité cumulée associe plusieurs obstacles.','La personne décrit difficultés de paiement, démarches et ressources limitées.','Le médecin observe la faisabilité du parcours plutôt qu’une apparence sociale.','Le soutien doit corriger le maillon qui empêche réellement l’accès.')],
 criteria='Le constat situationnel exige de préciser la prestation nécessaire, son absence ou son report et le rôle du coût selon le récit et les éléments disponibles. Le droit individuel à un subside ou à une autre prestation n’est pas diagnostiqué par le médecin: l’autorité ou l’assureur compétent applique les conditions du cas. Une prime élevée n’établit pas à elle seule un droit précis.',
 tests=[('Le bilan d’accès décrit le besoin non satisfait.','Le médecin précise prestation, indication, délai et conséquence du report.','Un soin obtenu ne signifie pas que tous les besoins sont couverts.','La priorité dépend de la gravité clinique et de l’obstacle restant.'),('Le décompte d’assurance clarifie le reste à charge.','Avec l’accord du patient, le service compétent examine l’année, la franchise et les exceptions applicables.','Une estimation non confirmée reste une estimation.','Le plan évite une promesse de prise en charge avant vérification.'),('L’examen du droit à la réduction des primes relève du canton.','Le service social vérifie la procédure et les pièces à jour avec la personne.','Une demande déposée peut rester incomplète ou en attente.','Le suivi contrôle la réponse et l’effet sur la prime effectivement due.'),('Une évaluation sociale approfondie explore la précarité persistante.','Le médecin formule le problème de santé et transmet les informations nécessaires dans le cadre autorisé.','La réponse peut résoudre un coût sans régler le logement ou le transport.','Les autres obstacles restent suivis séparément.')],
 urgent=['Le médecin recherche immédiatement si un report de soin ou un arrêt de traitement a déjà créé une aggravation clinique. Il traite cette aggravation selon sa gravité et ne réduit pas la consultation à un formulaire.','Il vérifie les besoins essentiels qui ne peuvent pas attendre et contacte le service disponible adapté au contexte. Un interlocuteur identifié remplace une simple liste d’adresses remise sans explication.','Il recueille l’accord pour les échanges nécessaires et transmet le besoin clinique utile, sans divulguer tout le dossier. Il distingue l’indication médicale et la décision de financement.','Avant la fin du contact, il vérifie ce qui a effectivement été obtenu et ce qui reste à résoudre. Si l’accès reste impossible, il revoit le plan de soin et le niveau de relais.'],
 care=[('Le but immédiat est de rétablir l’accès au soin prioritaire.','Le médecin et la personne identifient un obstacle précis et la prochaine action réalisable.','Le résultat est un soin accessible, pas seulement un courrier rédigé.'),('Les coûts sont expliqués avec leurs exceptions.','Le parcours distingue prime, franchise, quote-part et contribution hospitalière selon la situation applicable.','Les montants ordinaires ne se transposent pas à toute prestation ni à tout âge.'),('La réduction des primes est examinée sans garantie préalable.','La demande suit les règles du canton et les circonstances économiques actuelles.','Le versement à l’assureur réduit la prime; il ne rend pas toutes les prestations gratuites.'),('Le soutien à l’autogestion inclut les ressources matérielles.','Le plan choisit une organisation compatible avec les moyens et la compréhension disponibles.','Une simplification ne doit pas supprimer arbitrairement un soin nécessaire.')],
 follow=[('L’accès au soin est vérifié à l’échéance adaptée à sa nécessité.','Le médecin confirme le rendez-vous, la délivrance ou le relais réellement obtenu.','Un échec impose de reprendre le maillon bloquant.'),('La démarche financière est suivie jusqu’à une réponse exploitable.','La personne et le service social vérifient pièces manquantes et interlocuteur.','Une décision défavorable demande une explication des suites possibles par le service compétent.'),('L’état clinique est réévalué indépendamment du résultat administratif.','Le médecin recherche l’effet des soins reportés et l’évolution de la maladie.','Une amélioration financière ne prouve pas à elle seule une amélioration médicale.')],
 pitfalls=[('Une personne paie sa prime et pense que tout soin est gratuit.','Le médecin distingue les composantes et vérifie la prestation.','L’assurance obligatoire n’efface pas toute participation.'),('Une demande de subside a été déposée mais le soin reste reporté.','Le médecin vérifie réponse, transport et rendez-vous.','Une démarche administrative n’est pas un accès effectif.'),('La famille réclame les factures et le dossier complet.','Le médecin recherche le consentement et la nécessité de la transmission.','Une aide financière ne confère pas automatiquement un droit à tout le dossier médical.')]
),
3: dict(
 refs=['S05','S06','S07','S17','S24','S28'],
 focus='La littératie décrit la possibilité d’accéder à l’information de santé, de la comprendre, de l’apprécier et de l’utiliser dans un contexte donné. Une barrière linguistique concerne la langue de l’échange. Ces dimensions peuvent se cumuler mais ne se confondent ni avec l’intelligence ni avec le discernement.',
 case='Une femme de 47 ans acquiesce pendant l’explication d’un nouveau plan mais ne peut pas montrer quand prendre les produits. Son fils répond à sa place. Elle converse dans la vie quotidienne en français mais préfère une autre langue pour les décisions complexes.',
 epi='L’enquête HLS19–21 réalisée en 2020 auprès de2 502 adultes rapporte49 % de littératie faible dans la population suisse étudiée. La fiche sur l’autogestion rapporte66 % de compétences faibles chez les personnes atteintes d’une maladie non transmissible. Ces construits, leurs dénominateurs et leur période restent distincts; ils ne prouvent pas qu’un patient allophone appartient à l’une de ces catégories.',
 mechanism=[('Une information trop complexe dépasse les ressources disponibles.','La reformulation fait apparaître ce que la personne a compris et peut utiliser.','Le professionnel réduit la complexité et vérifie la décision concrète.'),('Une langue commune de conversation ne garantit pas la précision médicale.','Le médecin demande la langue préférée pour la décision et les difficultés rencontrées.','Un interprète professionnel permet un échange complet et confidentiel.'),('La honte ou le rapport d’autorité peut masquer une incompréhension.','Le professionnel attribue la vérification à la qualité de son explication.','Une demande non jugeante encourage la personne à montrer ce qui reste difficile.')],
 diff=[('Une confusion aiguë ne doit pas être confondue avec une barrière de langue.','Le médecin recherche une modification récente de l’attention ou du comportement.','Un changement clinique aigu exige une évaluation médicale.','L’origine linguistique n’explique pas automatiquement une fluctuation récente.'),('Une difficulté sensorielle peut empêcher la compréhension.','Le médecin vérifie que la personne entend et voit le support utilisé.','Le support et les conditions d’échange sont adaptés avant de conclure.','Répéter plus fort un texte complexe ne corrige pas tous les obstacles.'),('Un refus informé reste possible malgré une communication adaptée.','Le médecin demande la raison et vérifie les conséquences comprises.','Il respecte une décision autonome dans le cadre applicable.','La différence d’avis ne prouve pas une faible littératie.'),('Une incapacité de discernement demande une évaluation propre.','Le médecin examine compréhension, appréciation, raisonnement et expression du choix pour la décision précise.','L’obstacle linguistique est corrigé autant que possible avant cette appréciation.','Un test de langue ne remplace pas l’évaluation du discernement.')],
 ask=[('Dans quelle langue souhaitez-vous discuter de cette décision?','Le choix précise les conditions d’un échange fiable.','Le médecin organise l’aide adaptée plutôt que de supposer une préférence.'),('Pour vérifier mon explication, pouvez-vous me montrer comment vous ferez?','Une démonstration décrit l’utilisation réelle de l’information.','Le médecin reprend les éléments manquants et vérifie de nouveau.'),('Qu’est-ce qui vous semble le plus difficile dans ce plan?','La difficulté peut relever du texte, du parcours, des moyens ou de la décision.','Le plan cible l’obstacle identifié et ne réduit pas tout à un niveau scolaire.'),('Qui souhaitez-vous associer à la discussion?','La réponse distingue le souhait du patient et l’intervention spontanée de l’entourage.','Le professionnel garantit une parole propre et précise les échanges autorisés.')],
 exam=[('La personne suit un échange adapté et décrit un choix cohérent.','Le médecin observe l’attention et la compréhension dans la langue ou le support approprié.','Une difficulté persistante déclenche une analyse clinique, sensorielle et décisionnelle plus précise.'),('La personne utilise correctement le support ou le dispositif expliqué.','Le médecin lui demande de montrer le geste sans jugement et observe chaque étape utile.','Une erreur conduit à reprendre l’apprentissage et à vérifier la sécurité du plan.'),('Le proche aide sans empêcher la parole personnelle.','Le médecin s’adresse directement au patient et propose un temps séparé si approprié.','Une pression ou une substitution de réponse impose de clarifier la volonté propre.')],
 syndromes=[('Le profil de communication inadéquate reste dépendant du contexte.','La personne peut dire qu’elle comprend tout en restant incapable d’appliquer la consigne.','La démonstration montre les étapes comprises et celles qui restent difficiles.','Une explication plus accessible peut modifier le résultat sans changer les capacités intrinsèques.'),('Le profil de décision incertaine persiste malgré les adaptations.','La personne ne peut pas expliquer les conséquences du choix pour elle-même.','Le médecin documente les conditions de l’entretien et les capacités observées.','Une évaluation du discernement peut alors être indiquée sans conclusion automatique.')],
 criteria='Le besoin d’aide est constaté par l’obstacle réel de communication ou d’utilisation de l’information. Aucun seuil de littératie populationnel ne diagnostique le discernement individuel. L’interprète traduit dans les deux sens, garde le secret et reste neutre; le médecin conserve la responsabilité de l’explication, de la décision clinique et du consentement.',
 tests=[('La reformulation explore la compréhension opérationnelle.','Le médecin explique un petit nombre de messages utiles puis demande une démonstration personnelle.','Une reformulation partielle indique ce qui doit être repris; elle n’est pas une note d’intelligence.','Le plan est simplifié puis revérifié.'),('L’interprétariat professionnel permet un échange fiable.','Le professionnel réserve la langue et le mode adaptés et s’adresse directement au patient.','Une traduction fidèle ne garantit pas à elle seule l’accord ou la compréhension.','Le médecin vérifie à nouveau la décision et son application.'),('L’évaluation sensorielle ou cognitive répond à un doute clinique.','Le médecin choisit un outil adapté à la langue et au contexte plutôt qu’un test non validé improvisé.','Un résultat sous mauvaise condition n’est pas interprété comme une preuve de déficit.','Les limites et les adaptations sont consignées.'),('L’évaluation du discernement suit une question décisionnelle.','Le médecin applique la démarche ASSM au choix précis et aux conditions améliorées de communication.','Une incapacité pour un acte ne se généralise pas sans réévaluation.','La représentation et le soin urgent suivent ensuite le cadre légal applicable.')],
 urgent=['Le médecin recherche d’abord si l’incompréhension expose déjà la personne à un danger immédiat, par exemple une prise différente du plan prévu. Il fait préciser ce qui a été pris ou réalisé plutôt que de supposer une erreur.','Il organise sans délai une communication fiable pour les éléments de sécurité et évalue le besoin d’un soin urgent selon les faits. Il ne laisse pas un support incompris constituer l’unique protection.','Si la personne ne peut pas décider et qu’un soin urgent est nécessaire, il applique le cadre légal du soin urgent avec les informations disponibles. Il documente les obstacles, les adaptations et la volonté connue.','Après stabilisation, il reconstruit une explication accessible, vérifie la démonstration et attribue le relais. La fin de l’urgence n’autorise pas à renvoyer la personne avec le même document inexploitable.'],
 care=[('Le but est une décision et une action comprises.','Le médecin choisit les messages essentiels et adapte mots, rythme et support.','La personne explique ce qu’elle fera et à qui elle s’adressera si un problème apparaît.'),('L’interprète professionnel est intégré à la consultation.','Le médecin prépare le sujet et s’adresse au patient; il laisse le temps à la traduction.','Le proche n’est pas présumé neutre ni disponible pour toute information sensible.'),('Le financement est clarifié avant d’être promis.','Les modalités varient selon le canton et le cadre de soin; le service compétent les vérifie.','Une aide utile n’est pas annoncée comme automatiquement gratuite.'),('Le parcours est rendu praticable.','Le plan peut associer aide à la prise de rendez-vous, support lisible et démonstration.','Un message compris mais matériellement impossible demande encore une correction du parcours.')],
 follow=[('La compréhension est vérifiée lors des changements du plan.','La personne montre les étapes nouvelles et les points de sécurité.','Un ancien apprentissage réussi ne garantit pas l’utilisation d’un nouveau dispositif.'),('La réalisation est comparée à la décision annoncée.','Le professionnel demande ce qui a réellement été possible.','Une différence conduit à rechercher une cause avant de conclure à un refus.'),('Les conditions d’échange sont conservées dans le relais.','La transmission indique langue préférée, aide utile et points encore incertains.','L’équipe suivante vérifie de nouveau au lieu de déduire le discernement d’une ancienne note.')],
 pitfalls=[('Une personne parle couramment mais ne comprend pas le choix thérapeutique.','Le médecin propose une aide linguistique et vérifie les conséquences comprises.','La conversation quotidienne ne valide pas toute communication médicale.'),('Un proche traduit et choisit à la place du patient.','Le médecin organise une parole personnelle avec un interprète adapté.','L’aide familiale ne remplace pas automatiquement le consentement.'),('La reformulation contient une erreur.','Le médecin améliore l’explication puis la vérifie.','Une erreur de compréhension ne suffit pas à conclure à l’incapacité.')]
),
4: dict(
 refs=['S08','S09','S24','S25','S17'],
 focus='L’épuisement du proche aidant décrit ici une charge devenue difficilement soutenable dans le contexte des aides fournies. Il n’est ni un diagnostic biologique ni un jugement sur l’affection du proche. L’évaluation sépare les besoins de la personne malade, les tâches effectivement assumées et les ressources de l’aidant.',
 case='Un homme de 73 ans accompagne sa conjointe dépendante. Il assure les déplacements et se lève plusieurs fois la nuit. Il accepte son retour à domicile mais dit en aparté qu’il ne peut plus continuer et qu’aucun relais n’est confirmé.',
 epi='L’OFSP rapporte une estimation de592 000 proches aidants en 2018, dont49 000 jeunes de9à15 ans. Cette estimation de personnes qui aident n’est pas une prévalence actuelle d’épuisement. L’outil qualitatif pour cabinets médicaux a été publié en janvier 2024; il ne fournit pas un seuil numérique de surcharge applicable à tous.',
 mechanism=[('Les tâches répétées et nocturnes réduisent les possibilités de récupération.','Le clinicien précise la fréquence, la durée et le retentissement des aides.','Le plan cherche une décharge correspondant aux tâches les plus coûteuses.'),('L’aide peut devenir irremplaçable dans l’organisation actuelle.','La grille compare charge objective, charge ressentie et soutien professionnel.','Une nouvelle répartition prévient la rupture du système d’aide.'),('L’accord affectif ne garantit pas une capacité matérielle.','Le médecin demande ce que l’aidant peut réellement assurer et ce qu’il ne peut plus faire.','Le retour est conditionné à des moyens disponibles et acceptés plutôt qu’à une promesse générale.')],
 diff=[('La sécurité du malade peut être déjà compromise.','Le médecin identifie les soins essentiels qui ne sont plus assurés.','Un relais urgent est organisé si un besoin ne peut attendre.','Dire que la famille sera présente ne définit pas qui fera quoi.'),('La santé de l’aidant demande une évaluation propre.','L’entretien recherche symptômes, sommeil, détresse et retentissement fonctionnel.','Une urgence ou une maladie de l’aidant suit son propre parcours clinique.','La consultation du proche ne se réduit pas à la disponibilité pour le malade.'),('Un conflit de souhaits peut exister sans incapacité.','Le médecin entend séparément les préférences et les limites des personnes concernées.','Il cherche une organisation compatible avec leurs droits.','L’épuisement n’autorise pas à décider automatiquement à la place du malade.'),('Un besoin de protection peut dépasser une simple coordination.','Le professionnel décrit les faits et examine le secret et les règles applicables.','Le recours à l’autorité suit une base vérifiée et un besoin réel.','Un signalement ne remplace pas le soin immédiat ni une aide concrète.')],
 ask=[('Quelles tâches faites-vous vous-même et à quelle fréquence?','Le détail distingue présence, organisation, aide pratique, soins et garde.','Le clinicien attribue chaque besoin à une personne ou à un service réel.'),('Quelles tâches vous pèsent le plus et que ne pouvez-vous plus assurer?','La charge subjective ne se déduit pas du nombre de tâches.','Le plan priorise la décharge selon la charge et le risque.'),('Qui peut prendre le relais le jour et la nuit?','Les périodes sans soutien exposent à une rupture même si une aide partielle existe.','L’équipe vérifie accord, horaires et capacité du relais proposé.'),('Qu’aimeriez-vous changer pour continuer dans des conditions acceptables?','La préférence de l’aidant est une donnée propre et non un refus de solidarité.','La solution est négociée sans imposer un rôle illimité.')],
 exam=[('L’aidant peut décrire ses besoins et garder un fonctionnement acceptable.','Le médecin explore sommeil, symptômes et retentissement dans une consultation appropriée.','Une plainte physique ou psychique importante déclenche une évaluation dédiée.'),('Les tâches essentielles sont réalisables avec les moyens présents.','L’équipe vérifie les capacités fonctionnelles utiles et le matériel selon les besoins.','Une aide annoncée mais impossible à fournir impose de revoir le plan.'),('La personne malade peut participer aux décisions selon ses capacités.','Le médecin recherche compréhension et souhaits dans un échange adapté.','Le besoin d’aide physique n’établit pas une incapacité de discernement.')],
 syndromes=[('Le profil de surcharge associe tâches et retentissement.','L’aidant rapporte fatigue, absence de récupération et difficultés à continuer.','L’évaluation ne cherche pas un signe physique unique d’épuisement; elle examine les plaintes réelles.','La décharge cible les tâches qui entretiennent la surcharge.'),('Le profil de rupture imminente concerne les besoins non couverts.','L’aidant annonce une limite ou une absence de relais.','La vérification pratique identifie une période ou un soin laissé sans responsable.','Le niveau d’urgence dépend du besoin découvert, pas d’un score global improvisé.')],
 criteria='L’outil OFSP 2024 est un recensement qualitatif interprofessionnel. Il croise type de tâche, fréquence, charge ressentie, soutien professionnel et besoin de décharge. Une note élevée n’est pas inventée: le constat porte sur les tâches et leurs conséquences, puis les mesures prioritaires convenues et le moment de réévaluation.',
 tests=[('La grille OFSP décrit l’aide réelle.','Le professionnel la remplit avec l’aidant et les personnes concernées dans le cadre approprié.','Une charge faible dans une rubrique ne neutralise pas une garde nocturne insoutenable.','Les mesures prioritaires sont décidées et inscrites au dossier.'),('L’entretien propre à l’aidant explore sa santé.','Le médecin clarifie son statut de patient et les conditions de confidentialité.','Une plainte demande son raisonnement clinique, sans diagnostic automatique d’épuisement.','Les soins de l’aidant ne sont pas subordonnés à sa fonction auprès du malade.'),('Le bilan fonctionnel vérifie les besoins d’assistance.','L’équipe décrit transferts, alimentation, soins et surveillance nécessaires.','Une réussite en institution peut dépendre d’une aide absente au domicile.','Le lieu de vie et les moyens changent la décision de sortie.'),('L’évaluation sociale approfondie vérifie les relais.','Le service compétent confirme disponibilité, conditions et financement.','Une demande en attente ne constitue pas une décharge opérationnelle.','Le plan garde une solution pour les périodes encore découvertes.')],
 urgent=['Le médecin sépare immédiatement deux questions: le malade reçoit-il les soins essentiels et l’aidant présente-t-il lui-même une urgence? Il ne demande pas à l’aidant épuisé de compenser seul un danger constaté.','L’équipe identifie la tâche qui ne peut attendre et le relais capable de l’assurer. Si le lieu prévu ne permet pas la sécurité, elle réévalue le cadre de soins.','Les échanges respectent les souhaits et le secret pour chaque personne. Si le discernement manque, le médecin vérifie la représentation légale et les conditions d’urgence.','La transmission attribue les tâches, les horaires et le contact de recours. Le retour à domicile ne doit pas reposer sur une aide qui a explicitement annoncé ne plus pouvoir l’assurer.'],
 care=[('Le but est une aide soutenable et sûre.','L’équipe choisit les tâches prioritaires à redistribuer avec l’aidant et le malade.','La présence d’un relais accepté est vérifiée, avec les périodes non couvertes.'),('La décharge correspond au besoin réel.','Elle peut concerner garde, aide pratique, soins ou coordination selon les ressources disponibles.','Une brochure d’information ne remplace pas une prestation nécessaire.'),('Les droits liés au travail sont vérifiés dans leur champ.','Le congé court de prise en charge et le congé pour enfant gravement atteint suivent des règles distinctes.','Les plafonds légaux ne constituent pas une allocation automatique dans toute situation d’aide.'),('La santé de l’aidant garde une place propre.','Le médecin organise une consultation et les soins nécessaires selon ses symptômes.','Un meilleur fonctionnement du malade ne suffit pas à conclure que l’aidant va bien.')],
 follow=[('La charge est réévaluée après les mesures convenues.','La grille compare tâches, fréquence et charge ressentie.','Une mesure théorique sans effet sur la charge doit être reconsidérée.'),('Les relais sont vérifiés dans la durée.','L’équipe confirme les horaires, les absences et les solutions de remplacement.','Une interruption de prestation peut rouvrir un risque déjà résolu.'),('Les préférences et les capacités évoluent.','Le médecin redemande ce que chacun souhaite et peut assurer.','Un accord ancien ne vaut pas engagement illimité pour une charge nouvelle.')],
 pitfalls=[('Un conjoint dit oui au retour mais ne peut plus assurer les nuits.','L’équipe vérifie un relais nocturne avant de conclure à une sortie sûre.','L’accord affectif ne prouve pas la capacité pratique.'),('Le malade est dépendant mais comprend parfaitement le choix.','Le médecin recueille son consentement propre.','La dépendance physique ne vaut pas incapacité de discernement.'),('Un salarié demande quatorze semaines pour aider tout proche malade.','Le médecin distingue les champs des congés et oriente vers la vérification compétente.','Les deux régimes légaux ne sont pas interchangeables.')]
),
5: dict(
 refs=['S19','S34','S27','S25','S28','S22'],
 focus='L’incapacité de travail compare une atteinte à la santé et les exigences d’une activité précise. Elle se distingue du taux d’invalidité, du chômage et d’une difficulté sociale isolée. La réadaptation vise une participation compatible avec les capacités et les ressources disponibles.',
 case='Une employée de 54 ans ne supporte plus le rythme complet de son poste après une aggravation chronique. Elle peut accomplir certaines tâches assises mais craint qu’un retour partiel signifie qu’elle doit fournir le même rendement qu’avant. L’employeur demande le diagnostic complet.',
 epi='Les articles Suva 2025 consultés décrivent la qualité de l’évaluation et de la reprise; ils ne fournissent pas une prévalence suisse unique de ce scénario. Une proportion d’arrêt observée dans un groupe professionnel ne s’applique pas automatiquement à une autre maladie ou à un autre poste.',
 mechanism=[('Une atteinte peut réduire l’endurance ou certaines fonctions.','Le médecin confronte les limitations aux tâches concrètes et à leur durée.','Le poste et le rythme sont adaptés aux capacités résiduelles.'),('Une absence prolongée peut fragiliser la structure quotidienne et le lien professionnel.','Le suivi explore ressources, craintes et possibilités de contact compatible.','Une reprise progressive surveillée peut appartenir au projet thérapeutique sans nier les limitations.'),('Une confusion entre temps et rendement rend le certificat imprécis.','Le médecin décrit séparément présence possible et intensité de la prestation.','La coordination utilise un profil fonctionnel intelligible et réévaluable.')],
 diff=[('Une aggravation médicale peut rendre certaines tâches dangereuses.','Le médecin évalue l’état et les exigences de sécurité de l’activité.','Le certificat et les soins répondent aux limitations constatées.','Le souhait de maintenir un lien ne justifie pas une tâche actuellement dangereuse.'),('Une difficulté au poste peut aussi relever d’un conflit ou d’un obstacle organisationnel.','L’entretien distingue faits médicaux, exigences et contexte rapporté.','Le médecin précise son périmètre et les autres interlocuteurs utiles.','Un conflit ne prouve ni une maladie ni l’absence d’une maladie associée.'),('Une capacité dans une activité adaptée diffère de la capacité au poste habituel.','Le profil décrit les fonctions possibles dans chaque contexte.','La réadaptation examine les adaptations concrètes.','Un diagnostic identique n’implique pas la même incapacité dans tous les métiers.'),('Le droit à une rente relève de conditions distinctes.','L’office AI examine réadaptation, durée et invalidité selon la loi.','Le médecin documente sans décider lui-même de la prestation.','Le pourcentage d’arrêt de travail n’est pas le taux d’invalidité.')],
 ask=[('Quelles tâches, quels horaires et quelles contraintes votre poste comporte-t-il?','Une capacité n’a de sens que par rapport à une activité.','Le médecin demande une description précise plutôt qu’un simple intitulé de métier.'),('Qu’est-ce que vous pouvez encore faire et pendant combien de temps?','Les capacités résiduelles orientent une adaptation réaliste.','Le médecin distingue endurance, gestes et rythme sans inventer une capacité mesurée.'),('Quelles adaptations sont disponibles et acceptables?','Une possibilité théorique ne garantit pas un poste réellement aménagé.','Le plan est discuté avec les interlocuteurs autorisés et vérifie les conditions concrètes.'),('Quelles informations acceptez-vous de transmettre et à qui?','La coordination doit respecter le secret et l’objet de l’échange.','Le certificat destiné à l’employeur privilégie les informations fonctionnelles nécessaires.')],
 exam=[('Le fonctionnement observé est cohérent avec les activités décrites.','Le médecin examine les fonctions pertinentes selon la maladie et les plaintes.','Une observation brève ne permet pas à elle seule d’affirmer l’endurance sur une journée.'),('La personne peut réaliser une tâche dans des conditions précisées.','L’évaluation décrit effort, durée, aides et récupération utiles.','Une discordance justifie une clarification et éventuellement une évaluation spécialisée.'),('Les conditions de sécurité de l’activité sont satisfaites.','Le médecin examine les fonctions indispensables au poste et les effets des traitements selon les données disponibles.','Une aptitude particulière, dont la conduite, demande son cadre propre et ne se déduit pas d’un taux d’arrêt.')],
 syndromes=[('Le profil de limitation fonctionnelle relie santé et activité.','La personne décrit douleur, fatigabilité ou difficulté de concentration selon son état.','L’examen recherche les éléments pertinents sans supposer que l’intensité ressentie donne directement un pourcentage.','L’évaluation croise constats, évolution et exigences.'),('Le profil de désinsertion associe durée et obstacles de reprise.','La personne décrit perte de repères, crainte ou absence d’adaptation.','Le médecin analyse les ressources et les contraintes avec l’équipe concernée.','La réponse associe soins et réadaptation plutôt qu’une prolongation automatique du même plan.')],
 criteria='Le constat médical porte sur les limitations liées à la santé et les capacités dans l’activité précisée. Le certificat distingue durée, taux, présence et rendement selon le besoin. La loi AI impose ses propres conditions cumulatives pour la rente; l’appréciation médicale reste une base de décision et ne remplace pas l’instance d’application du droit.',
 tests=[('La description du poste constitue une référence de comparaison.','Le médecin recueille les tâches, efforts, horaires et contraintes de sécurité avec la personne.','Un poste mal connu limite la solidité de l’estimation.','La demande d’information complémentaire porte sur les exigences utiles.'),('L’examen clinique documente l’atteinte et les fonctions.','Les mesures choisies répondent à la maladie et aux tâches concernées.','Une normalité partielle n’exclut pas toute limitation; une anomalie ne donne pas seule un pourcentage.','Le raisonnement explique le lien entre constat et restriction.'),('Une évaluation spécialisée clarifie une discordance.','Le médecin pose une question fonctionnelle précise et transmet les données autorisées.','Une conclusion doit rester rapportée aux conditions d’évaluation.','Le plan est révisé avec les nouvelles informations.'),('La réévaluation de reprise décrit l’effet de l’adaptation.','Le suivi compare tâches réalisées, tolérance et capacité au rythme convenu.','Une présence obtenue avec un rendement réduit ne vaut pas retour à la pleine prestation.','La progression ou la révision dépend du fonctionnement et de la sécurité.')],
 urgent=['Le médecin recherche d’abord une aggravation qui rend l’activité ou le trajet dangereux et organise les soins nécessaires. Il ne réduit pas la demande à un pourcentage administratif.','Il précise les restrictions utiles pour éviter une tâche incompatible avec l’état actuel. Une évaluation d’aptitude particulière peut nécessiter un interlocuteur et des règles distincts.','La transmission à l’employeur reste fonctionnelle et proportionnée dans le cadre autorisé. Le diagnostic n’est pas inscrit par réflexe sur le certificat destiné à cet usage.','Le plan de reprise attribue un interlocuteur, une réévaluation et une conduite en cas d’échec. Une adaptation non disponible oblige à revoir la proposition plutôt qu’à la présenter comme déjà acquise.'],
 care=[('Le but est une participation sûre et compatible avec la santé.','Le médecin décrit ce qui est possible et ce qui doit être évité.','La reprise ne se résume pas à une date sans conditions de travail.'),('La présence et le rendement sont distingués.','Le plan précise les ordres de grandeur et les tâches adaptées.','Le calcul dérivé de50 % de présence et50 % de rendement donne25 % de capacité globale, soit75 % d’incapacité dans l’exemple Suva; il ne prescrit pas ce schéma au patient.'),('La réadaptation est coordonnée sans promesse de rente.','Les données fonctionnelles et l’évolution sont adressées à l’interlocuteur compétent avec les autorisations nécessaires.','L’ouverture d’un droit reste une décision de l’organisme responsable.'),('La protection du contrat est distinguée du salaire.','Le régime contractuel, les dates et l’année de service sont vérifiés avant un avis juridique.','Les périodes de protection contre la résiliation ne garantissent pas le salaire pour la même durée.')],
 follow=[('La reprise est réévaluée selon l’évolution et les conditions réelles.','Le médecin demande tâches, durée, récupération et difficultés.','Une aggravation ou une adaptation inexistante impose de réviser le plan.'),('Le certificat reste limité à ce qui est documenté.','La réévaluation explique la persistance ou la modification des restrictions.','Une prolongation automatique sans examen de l’évolution affaiblit la décision.'),('Le parcours d’assurance est suivi sans se substituer à l’office.','Le médecin répond aux questions médicales et distingue les données manquantes.','Un silence administratif ne vaut ni accord ni refus de la prestation.')],
 pitfalls=[('Un salarié est présent à moitié et travaille à moitié du rendement habituel.','Le calcul donne une capacité globale de25 % dans cet exemple.','Le taux de présence seul ne représente pas toute la prestation.'),('L’employeur demande le diagnostic pour aménager le poste.','Le médecin clarifie l’autorisation et fournit les limitations nécessaires.','L’utilité d’un échange ne supprime pas le secret professionnel.'),('Une personne a 100 %d’arrêt et demande automatiquement100 % de rente.','Le médecin distingue incapacité de travail, invalidité et quotité de rente.','Les trois notions suivent des décisions et des règles distinctes.')]
)
}
SCENARIOS.update({
6: dict(
 refs=['S10','S02','S09','S21','S24','S28'],
 focus='La solitude est une expérience pénible liée à la perception de relations insuffisantes. L’isolement décrit plutôt la disponibilité des contacts ou des aides. Une personne peut vivre seule sans souffrir de solitude, ou souffrir malgré un entourage nombreux.',
 case='Un homme de 79 ans vit seul après un deuil. Il dit ne déranger personne et manque un suivi parce qu’il ne sait pas qui pourrait l’accompagner. Il reçoit des appels réguliers mais ne les décrit pas comme des relations satisfaisantes.',
 epi='L’indicateur Obsan mis à jour en janvier 2025 utilise l’Enquête suisse sur la santé chez les personnes de15 ans et plus en ménage privé. Il retient un sentiment de solitude assez ou très fréquent. Le graphique n’a pas fourni de valeur numérique exploitable dans les passages consultés; aucune prévalence n’est inventée.',
 mechanism=[('Un besoin relationnel non satisfait peut produire une détresse.','Le médecin demande la qualité perçue des liens et le souhait personnel.','Le plan vise un contact choisi plutôt qu’un nombre imposé de visites.'),('L’absence d’aide disponible peut empêcher un soin nécessaire.','Le bilan distingue personnes connues et aide effectivement mobilisable.','Le relais répond à la tâche et au moment où l’aide est nécessaire.'),('Une maladie peut réduire les possibilités de participation.','L’entretien recherche mobilité, audition, transport et fatigabilité.','L’accès à une relation ou une activité est adapté aux fonctions et aux préférences.')],
 diff=[('Une dépression ou un danger psychique associé doit être recherché.','Le médecin explore humeur, intérêt, fonctionnement et propos sur la mort.','Un danger actuel impose une évaluation et un relais adaptés.','La solitude n’explique pas à elle seule tous les symptômes dépressifs.'),('Un isolement choisi peut ne pas être un problème pour la personne.','Le médecin demande si la situation est satisfaisante et quelles aides seraient souhaitées.','Il respecte la préférence tout en vérifiant les besoins essentiels.','Vivre seul n’est pas un diagnostic.'),('Une barrière fonctionnelle peut expliquer une faible participation.','Le bilan recherche les limites sensorielles, physiques et matérielles.','Le plan corrige l’accès avant de conclure au manque de motivation.','Une invitation ne suffit pas si la personne ne peut pas se déplacer.'),('Un besoin de protection peut exister si les besoins essentiels ne sont plus couverts.','Le médecin décrit les faits et apprécie le discernement pour les décisions concernées.','Le recours à l’aide ou à l’autorité respecte les bases applicables.','La vulnérabilité ne supprime pas automatiquement l’autonomie.')],
 ask=[('Vos relations vous conviennent-elles actuellement?','La question vise le vécu plutôt que le nombre de personnes connues.','Le médecin précise ce que la personne souhaite changer ou préserver.'),('Qui pourriez-vous joindre si un besoin de soin apparaissait?','La disponibilité pratique d’un relais diffère de la qualité affective des liens.','Le plan vérifie un contact et sa capacité réelle.'),('Qu’est-ce qui vous empêche de participer à une activité qui vous plairait?','La réponse identifie une difficulté fonctionnelle ou matérielle modifiable.','La solution tient compte du transport, de l’effort et des préférences.'),('Comment vont votre humeur, votre sommeil et vos journées?','Une souffrance psychique associée peut nécessiter une prise en charge propre.','Le médecin examine le retentissement et le danger sans poser un diagnostic sur la seule solitude.')],
 exam=[('La personne peut décrire un projet et demander une aide adaptée.','Le médecin observe communication, compréhension et fonctionnement pendant l’échange.','Une modification récente ou une difficulté importante justifie une évaluation clinique propre.'),('Les fonctions utiles à l’activité souhaitée sont suffisantes avec les aides présentes.','L’équipe vérifie mobilité, accès sensoriel et moyens de déplacement selon les besoins.','Une limitation concrète appelle une adaptation plutôt qu’une injonction à sortir.'),('Les besoins quotidiens essentiels sont couverts.','L’entretien décrit repas, traitements et recours en cas de problème.','Un besoin non couvert change la priorité du relais et peut rendre une sortie inadaptée.')],
 syndromes=[('Le profil de solitude subjective repose sur le vécu.','La personne décrit un manque de proximité ou d’affection.','Aucun signe physique unique ne confirme ce vécu; le médecin écoute et recherche le retentissement.','La réponse est choisie selon le besoin exprimé.'),('Le profil d’isolement pratique concerne les aides mobilisables.','La personne ne trouve pas de soutien pour une tâche importante.','L’évaluation vérifie les fonctions et les ressources disponibles.','Le relais cible l’aide manquante sans supposer une souffrance relationnelle identique.')],
 criteria='Le diagnostic situationnel distingue perception des relations, réseau réel, besoin d’aide et souhait de changement. La question Obsan décrit un indicateur de population et n’est pas un test de discernement ni un diagnostic de dépression. Une situation stable et choisie ne justifie pas une intervention imposée sans autre motif.',
 tests=[('L’entretien relationnel constitue la première référence.','Le médecin interroge satisfaction, fréquence vécue et évolution récente.','Une réponse rassurante n’exclut pas un besoin pratique.','Le plan garde les dimensions séparées.'),('La cartographie du réseau décrit des possibilités réelles.','La personne identifie contacts, rôle accepté et disponibilité.','Une liste de noms n’est pas un engagement de soutien.','Le relais est confirmé pour la tâche retenue.'),('L’évaluation fonctionnelle répond à une activité choisie.','Les professionnels recherchent les obstacles qui rendent la participation difficile.','Une possibilité théorique n’est pas une activité accessible.','Le plan associe une adaptation et un essai acceptable.'),('L’évaluation psychique approfondie est indiquée selon les symptômes.','Le médecin explore les hypothèses cliniques et la sécurité.','Un score non consulté n’est pas reconstruit.','La dépression ou le danger suivent leur propre prise en charge.')],
 urgent=['Le médecin recherche un danger clinique ou un besoin essentiel immédiatement découvert. Il ne traite pas une rupture de traitement ou une impossibilité d’alimentation par une simple proposition d’activité sociale.','Il évalue séparément une éventuelle souffrance psychique aiguë et les capacités de recours à l’aide. Si le cadre actuel ne permet pas la sécurité, un relais urgent est organisé.','Les proches ou services sont contactés dans le cadre autorisé et avec une tâche précise. Le médecin ne suppose pas qu’un voisin ou un enfant acceptera une surveillance.','La transmission précise le besoin, la personne qui prend le relais et ce qui doit faire réévaluer la situation. La sortie dépend du fonctionnement réel de cette organisation.'],
 care=[('Le but est une relation ou une aide que la personne souhaite et peut utiliser.','Le médecin choisit avec elle une première action accessible.','Le résultat est évalué sur son vécu et sur l’accès réel, pas seulement sur la présence à une activité.'),('Les obstacles matériels et fonctionnels sont traités.','Le plan vérifie transport, coût, langue et fatigue selon le cas.','Une offre intéressante mais inaccessible reste un besoin non résolu.'),('Le soutien relationnel ne remplace pas les soins d’une maladie associée.','La dépression, la douleur ou une limitation sensorielle sont évaluées et traitées dans leur cadre.','L’absence de changement malgré un contact demande de reprendre l’hypothèse.'),('La préférence et la confidentialité guident les échanges.','Le médecin demande qui peut recevoir quelles informations.','Une intention bienveillante ne constitue pas à elle seule une levée du secret.')],
 follow=[('Le vécu de la personne est redemandé après l’action convenue.','Elle décrit ce qui a été satisfaisant ou difficile.','Une présence sans bénéfice perçu peut demander une autre approche.'),('L’aide pratique est vérifiée au moment nécessaire.','L’équipe confirme que la tâche a été assurée.','Un contact social ne remplace pas un soin ou un transport absent.'),('Les symptômes associés sont suivis séparément.','Le médecin recherche une aggravation physique ou psychique.','Une amélioration relationnelle n’autorise pas à clore une évaluation clinique nécessaire.')],
 pitfalls=[('Une personne vit seule et se dit satisfaite.','Le médecin vérifie les besoins et respecte le choix.','La vie solitaire ne prouve pas une solitude subie.'),('Un patient connaît beaucoup de monde mais ne peut joindre personne pour un soin.','Le médecin vérifie l’aide mobilisable et organise le relais utile.','Le nombre de contacts ne mesure pas leur disponibilité.'),('Une activité est proposée loin du domicile à une personne peu mobile.','Le plan vérifie l’accès et les préférences avant de conclure à un refus.','Une offre ne devient pas accessible par sa seule existence.')]
),
7: dict(
 refs=['S11','S12','S32','S24','S23','S02'],
 focus='La chaleur peut provoquer une atteinte aiguë ou aggraver une maladie chronique. Le scénario distingue exposition, symptômes et gravité actuelle. Une température extérieure ou une mesure corporelle isolée ne doit pas retarder l’aide devant une altération de l’état général.',
 case='Une femme de 82 ans vivant seule paraît confuse pendant une période très chaude. Elle a une maladie cardiaque et un traitement diurétique. Elle ne peut pas expliquer ce qu’elle a bu; son voisin propose de lui faire avaler rapidement une grande quantité d’eau.',
 epi='Le NCCS estime410 décès liés à la chaleur en Suisse en 2025, dont84 % chez les personnes deplus de75 ans. Il s’agit d’une estimation populationnelle attribuable à la chaleur, non d’un décompte individuel des seuls coups de chaleur. La fragilité et la maladie chronique rendent nécessaire un plan adapté.',
 mechanism=[('La chaleur exige une dissipation thermique et augmente les contraintes circulatoires.','Le médecin recherche exposition, durée, symptômes et signes de gravité.','Le rafraîchissement et l’évaluation urgente ne sont pas différés par un doute étiologique.'),('Les pertes hydriques et les traitements peuvent déstabiliser un équilibre fragile.','Le bilan précise prises, boissons habituelles, maladie rénale ou cardiaque et changements récents.','L’hydratation et les traitements sont réévalués individuellement.'),('L’isolement ou un logement difficile à rafraîchir limite la protection.','L’entretien vérifie les moyens réellement disponibles et le recours possible.','Le plan organise un lieu frais et un contact effectif pour la personne vulnérable.')],
 diff=[('Une atteinte grave liée à la chaleur exige une réponse immédiate.','Le médecin recherche confusion, inconscience ou impossibilité de boire.','Il appelle le 144 dans les situations décrites par la consigne cantonale et commence le rafraîchissement.','Il n’attend pas un seuil isolé pour agir devant un état inquiétant.'),('Une décompensation de la maladie chronique peut coexister.','L’évaluation recherche les signes propres à l’atteinte cardiaque, respiratoire ou rénale suspectée.','Les soins urgents suivent le retentissement clinique.','Une canicule n’explique pas automatiquement toute dyspnée.'),('Une autre cause aiguë peut produire confusion ou malaise.','Le médecin garde un diagnostic différentiel selon l’histoire et l’examen.','Il organise le bilan dans le niveau de soins adapté.','L’exposition thermique ne dispense pas d’examiner les autres hypothèses.'),('Une consigne de boisson inadaptée peut exposer à un autre risque.','Le bilan vérifie la capacité à avaler et les restrictions ou maladies associées.','La quantité est clarifiée avec le médecin en cas d’insuffisance cardiaque ou rénale.','Une recommandation populationnelle n’est pas une prescription universelle.')],
 ask=[('Depuis quand êtes-vous exposé à la chaleur et où pouvez-vous vous rafraîchir?','La réponse décrit la possibilité d’interrompre l’exposition.','Le plan vérifie un lieu accessible plutôt qu’un conseil abstrait.'),('Quels symptômes sont apparus et comment évoluent-ils?','L’évolution décrit la gravité et la nécessité d’une aide immédiate.','La confusion ou l’impossibilité de boire changent la conduite.'),('Quelles maladies, restrictions de boissons et prises réelles faut-il connaître?','L’équilibre hydrique et médicamenteux peut être fragile.','Le médecin réévalue individuellement sans arrêt automatique de tous les traitements.'),('Qui peut prendre de vos nouvelles et obtenir de l’aide?','Le recours est déterminant si l’état se dégrade à domicile.','Le plan confirme un contact et la conduite en cas de non-réponse.')],
 exam=[('La personne est éveillée et communique comme à son état habituel.','Le médecin évalue conscience, attention et évolution par rapport à la référence.','Une altération récente exige une prise en charge urgente adaptée.'),('La respiration et la circulation ne présentent pas de détresse apparente.','L’évaluation clinique recueille les paramètres accessibles sans retarder le relais nécessaire.','Une détresse clinique impose une réponse urgente même sans série complète de mesures.'),('La personne peut boire en sécurité si la voie orale est envisagée.','Le médecin vérifie conscience, capacité à avaler et contexte clinique.','Une personne inconsciente ne reçoit pas de liquide par la bouche; le relais urgent et le rafraîchissement priment.')],
 syndromes=[('Le profil de stress thermique associe exposition et symptômes.','La personne peut décrire vertiges, faiblesse, nausées ou céphalées.','Le médecin recherche les signes de gravité plutôt qu’un signe cutané obligatoire.','Les symptômes et l’état actuel déterminent la réponse.'),('Le profil de vulnérabilité associe maladie, traitement et environnement.','La personne peut manquer de boisson adaptée, de fraîcheur ou d’aide.','L’évaluation vérifie les capacités de protection et le retentissement organique suspecté.','Plusieurs facteurs se cumulent et appellent une prévention individualisée.')],
 criteria='La qualification clinique repose sur l’exposition et l’état actuel, en recherchant les diagnostics associés. La page cantonale mentionne une température corporelle supérieure à 40 °C parmi les signes de coup de chaleur et une altération neurologique; cette liste d’information ne doit pas être utilisée pour exclure une urgence si tous les signes ne sont pas réunis. La consigne d’appel au 144 en cas d’inconscience ou d’impossibilité de faire boire est explicitement lue.',
 tests=[('L’évaluation clinique de gravité constitue la première étape.','Le médecin recueille conscience, respiration, circulation et contexte thermique.','Un état inquiétant conduit au relais sans attendre un test confirmatoire.','Le rafraîchissement accompagne l’aide urgente.'),('La température renseigne le contexte physiologique.','La méthode et le moment sont consignés; la mesure ne retarde pas le traitement nécessaire.','Une valeur isolée ne décrit pas tout le retentissement.','La décision tient compte de l’état neurologique et des autres signes.'),('Le bilan biologique est orienté par la gravité et les organes à risque.','L’équipe compétente choisit les analyses selon le contexte clinique.','Aucun seuil électrolytique ou protocole de perfusion n’est inventé ici.','Le résultat guide une correction dans le cadre de soins approprié.'),('La revue des médicaments et du logement complète le bilan.','Le médecin vérifie les prises réelles et les possibilités de fraîcheur ou de contact.','Une liste correcte ne prouve pas un usage réel ni un logement protecteur.','La prévention corrige les vulnérabilités identifiées.')],
 urgent=['Dès le premier contact, le professionnel met fin à l’exposition si cela peut être fait en sécurité et évalue l’état de conscience et la possibilité de boire. En cas d’inconscience ou d’impossibilité de faire boire, il appelle le 144 selon la consigne cantonale.','Pendant l’attente, il déplace la personne vers un lieu frais si possible, applique de l’eau froide sur le corps et l’évente. Il ne force aucune prise orale chez une personne inconsciente.','La transmission précise exposition, changement d’état, maladie connue, prises médicamenteuses et actions déjà réalisées. Le rafraîchissement ne remplace pas l’évaluation des autres causes de décompensation.','Après stabilisation, le médecin vérifie le lieu de vie, la capacité à boire selon la prescription individuelle et l’existence d’un relais. Un retour au même environnement sans protection maintient le risque.'],
 care=[('Le but immédiat est de réduire l’exposition et de sécuriser l’état clinique.','Le rafraîchissement accompagne le niveau d’aide nécessaire.','Un bénéfice apparent transitoire ne suffit pas à exclure une atteinte grave.'),('La prévention hydrique est individualisée.','L’OFSP propose au moins 1,5 L/j dans son conseil populationnel mais demande une clarification médicale en cas d’insuffisance cardiaque ou rénale.','La quantité du patient n’est pas déduite automatiquement de ce repère.'),('Les traitements sont revus sans interruption générale improvisée.','Le médecin ou pharmacien vérifie les risques et une éventuelle adaptation selon la fiche pertinente.','Les doses, paliers et décisions propres à chaque produit restent à vérifier AIPS.'),('L’environnement et les contacts rendent la protection réelle.','Le plan associe fraîcheur, horaires adaptés et prise de nouvelles des personnes vulnérables.','Une alerte reçue sans moyen d’action ne constitue pas une protection suffisante.')],
 follow=[('L’état clinique est surveillé selon la gravité et l’équipe de prise en charge.','Le suivi reprend conscience, symptômes et fonction des organes concernés.','Toute aggravation réévalue immédiatement le niveau de soins.'),('Le plan hydrique et médicamenteux est réexaminé après l’épisode.','Le prescripteur clarifie les consignes individuelles et leur durée.','Le patient ne poursuit pas indéfiniment une adaptation temporaire sans réévaluation.'),('Les moyens de protection sont vérifiés au domicile.','Le relais confirme fraîcheur, boissons adaptées et contact disponible.','Une absence de réponse ou une aide manquante déclenche la conduite convenue.')],
 pitfalls=[('La personne est confuse mais sa température isolée paraît rassurante.','Le médecin évalue l’urgence clinique et ne conclut pas sur la seule valeur.','Un chiffre isolé ne neutralise pas l’altération neurologique.'),('Un voisin veut faire boire une personne inconsciente.','Le relais urgent est appelé et la prise orale est évitée; le rafraîchissement commence.','La voie orale ne devient pas sûre parce que la chaleur est suspectée.'),('Un patient insuffisant cardiaque demande une quantité standard d’eau.','Le médecin clarifie sa consigne individuelle.','Le repère de population ne remplace pas sa prescription adaptée.')]
),
8: dict(
 refs=['S13','S29','S31','S11','S02'],
 focus='La pollution extérieure représente une exposition environnementale susceptible d’aggraver la santé respiratoire ou cardiovasculaire. Une concentration ambiante ne constitue ni un diagnostic individuel ni une preuve suffisante de causalité. Le scénario conserve la priorité au patient symptomatique.',
 case='Une personne de 66 ans atteinte d’une maladie respiratoire présente une dyspnée nouvelle lors d’un épisode de mauvaise qualité de l’air. Elle pense pouvoir attendre parce que le taux affiché sur une application serait inférieur à une limite annuelle. Elle a aussi une douleur thoracique inhabituelle.',
 epi='L’OFEV décrit environ2 000 décès prématurés annuels attribuables à la pollution atmosphérique en Suisse dans la page consultée. Cette charge populationnelle n’identifie pas la cause d’un symptôme chez une personne. Les valeurs OPair ont été lues dans l’état du 1er août 2026; les propositions scientifiques CFHA 2023 sont distinctes du droit applicable.',
 mechanism=[('Les polluants atteignent les voies respiratoires et augmentent la charge d’exposition.','L’histoire précise symptômes, lieu, durée et activité.','La réduction d’exposition complète la prise en charge de la maladie.'),('Une maladie chronique peut limiter la réserve physiologique.','L’examen recherche la gravité de la décompensation et ses autres causes.','Les soins aigus ne sont pas retardés par une discussion de moyenne environnementale.'),('Une comparaison de périodes différentes peut fausser l’interprétation.','Le lecteur identifie polluant, unité et période de moyenne.','Le conseil sépare normes d’immission, recommandations et état clinique.')],
 diff=[('Une affection aiguë grave reste prioritaire devant dyspnée ou douleur.','Le médecin évalue l’état clinique et les symptômes associés.','Le parcours urgent est choisi selon la gravité actuelle.','Une pollution élevée n’exclut pas une autre urgence.'),('Une exacerbation de la maladie connue peut être présente.','Le bilan compare l’état actuel et la référence habituelle.','Le traitement suit la maladie et les prescriptions vérifiées.','L’exposition peut contribuer sans être l’unique cause.'),('Une exposition professionnelle ou intérieure peut se cumuler.','L’entretien précise les lieux, tâches et horaires.','Le bilan distingue les sources et les démarches compétentes.','La station extérieure ne mesure pas chaque exposition personnelle.'),('Une inquiétude liée à l’information peut augmenter le retentissement.','Le médecin écoute les symptômes sans les invalider et poursuit l’évaluation clinique.','Le conseil clarifie les données et les gestes utiles.','Une inquiétude ne prouve pas que le symptôme est imaginaire.')],
 ask=[('Quels symptômes sont nouveaux et quelle est leur évolution?','La réponse distingue une plainte chronique et un changement nécessitant une aide rapide.','Le médecin évalue la gravité avant les conseils d’exposition.'),('Où et pendant quelles activités l’exposition semble-t-elle importante?','Le lieu, la durée et l’effort modifient la description de l’exposition.','Le conseil vise une réduction réalisable sans supprimer toute activité par principe.'),('Quel polluant et quelle période l’application affiche-t-elle?','Une pointe horaire ne se compare pas directement à une moyenne annuelle.','Le médecin corrige la comparaison et garde la décision clinique séparée.'),('Quels traitements et plans de recours avez-vous déjà?','La continuité du traitement de fond et l’accès au soin restent essentiels.','Le prescripteur vérifie les adaptations plutôt que d’improviser un nouveau traitement environnemental.')],
 exam=[('La respiration est compatible avec l’état habituel.','Le médecin observe travail respiratoire, parole et symptômes, puis examine selon la maladie.','Une aggravation ou une détresse impose une évaluation dédiée sans attendre une mesure d’air.'),('La circulation ne présente pas de signe inquiétant dans le cadre évalué.','Le clinicien recherche les éléments correspondant à la douleur ou au malaise rapporté.','Une douleur thoracique nouvelle ne se résume pas à un indice de pollution.'),('Les informations d’exposition sont décrites sans surinterprétation.','Le médecin vérifie source, unité et période du résultat.','Une donnée environnementale rassurante ne rend pas normal un examen clinique anormal.')],
 syndromes=[('Le profil d’aggravation respiratoire exige un diagnostic clinique.','La personne décrit dyspnée, toux ou autres symptômes dans leur évolution.','L’examen recherche le retentissement et les signes propres aux hypothèses.','La temporalité d’exposition contribue au raisonnement sans prouver seule la cause.'),('Le profil d’exposition élevée relève aussi de la prévention collective.','La personne décrit un lieu ou une activité récurrente.','La donnée ambiante est reliée à sa période de mesure.','Les mesures environnementales et les soins individuels répondent à deux niveaux distincts.')],
 criteria='Il n’existe pas dans les sources consultées de test clinique unique attribuant toute dyspnée à la pollution extérieure. La qualification sépare la maladie diagnostiquée, le contexte d’exposition et la force des arguments de causalité. Une limite réglementaire protège à l’échelle de l’air ambiant et n’est pas un seuil de sécurité individuelle absolue.',
 tests=[('L’évaluation clinique précède l’interprétation environnementale.','Le médecin examine le changement d’état et les diagnostics graves plausibles.','Un symptôme important exige sa conduite même si les concentrations ambiantes sont faibles.','Le bilan suit l’indication clinique.'),('La donnée d’air renseigne une exposition ambiante.','Le lecteur précise polluant, unité, localisation et moyenne temporelle.','Une valeur annuelle ne permet pas de qualifier une pointe du jour.','La comparaison réglementaire utilise la même définition.'),('Les explorations de la maladie sont prescrites selon l’hypothèse.','Le médecin choisit les examens utiles pour la décompensation suspectée.','Une valeur normale isolée ne clôt pas toutes les hypothèses.','Le résultat change une décision clinique explicite.'),('L’évaluation spécialisée approfondit une évolution inhabituelle.','Le médecin transmet symptômes, résultats, contexte d’exposition et traitements.','L’expertise peut maintenir plusieurs causes simultanées.','La prévention d’exposition reste compatible avec le suivi de la maladie.')],
 urgent=['Le médecin traite d’abord la gravité de la dyspnée, de la douleur ou du malaise. Il n’attend pas un calcul environnemental pour organiser le niveau de soins nécessaire.','Il réduit l’exposition actuelle si cela est faisable sans retarder l’aide. Cette mesure accompagne les soins et ne remplace pas le traitement de la décompensation.','La transmission distingue les symptômes constatés et les données d’air disponibles. Elle ne présente pas la pollution comme cause démontrée en l’absence d’arguments suffisants.','Après stabilisation, le prescripteur vérifie le plan de recours et les moyens de réduire une exposition évitable. Le traitement chronique et la prévention environnementale restent coordonnés.'],
 care=[('Le but immédiat est de traiter la maladie ou la décompensation.','La conduite clinique dépend du diagnostic et de la gravité.','Le niveau de pollution ne se substitue pas à cette décision.'),('La réduction d’exposition reste proportionnée et réalisable.','La personne et le professionnel examinent lieux, horaires et effort selon les informations disponibles.','L’objectif n’est pas d’imposer une inactivité générale sans nécessité.'),('Les normes sont interprétées avec leur définition.','Les moyennes annuelles OPair sont 10 µg/m³ pour PM2,5, 20 pour PM10 et 30 pour NO2; la valeur ozone 120 µg/m³ porte sur une heure et au plus un dépassement annuel.','Une recommandation scientifique différente n’est pas annoncée comme loi en vigueur.'),('Les médicaments suivent la maladie et leur information professionnelle.','Aucune molécule ni dose n’est ajoutée sur le seul fondement d’un indice d’air.','Les paramètres non lus dans AIPS restent à vérifier avant toute prescription.')],
 follow=[('Le fonctionnement clinique est comparé à la référence.','Le médecin suit symptômes et évolution de la maladie.','Une aggravation persistante oblige à reprendre le diagnostic.'),('L’exposition et les mesures adoptées sont décrites.','La personne précise ce qu’elle a réellement pu modifier.','Une amélioration temporelle ne prouve pas à elle seule une causalité unique.'),('Les comparaisons réglementaires gardent la même période.','Le lecteur vérifie les unités et les dates des valeurs utilisées.','Une réforme annoncée n’est pas appliquée comme texte déjà en vigueur.')],
 pitfalls=[('Une pointe horaire est comparée à une limite annuelle.','Le candidat rétablit la période de moyenne avant la comparaison.','Deux nombres de même unité peuvent avoir des définitions différentes.'),('Un patient dyspnéique attend une baisse de l’indice d’air.','Le médecin évalue l’urgence et la décompensation actuelle.','L’exposition ne remplace pas le diagnostic clinique.'),('Un rapport scientifique propose une valeur plus basse que l’OPair.','Le cours distingue objectif de protection et droit applicable.','Une proposition n’est pas une norme entrée en vigueur.')]
),
9: dict(
 refs=['S14','S15','S16','S30','S24','S02'],
 focus='L’environnement intérieur regroupe des expositions de nature différente. La fumée et l’humidité peuvent participer à des symptômes; le radon concerne un risque pulmonaire à long terme évalué par une mesure adaptée. Le scénario ne confond pas une irritation actuelle et une attribution individuelle à un gaz non perçu.',
 case='Une famille décrit toux et irritation dans une chambre humide. Un parent atteint d’une maladie respiratoire présente une gêne accrue. Un appareil a affiché pendant deux jours une concentration de radon élevée, que la famille considère comme la preuve de la cause de tous les symptômes.',
 epi='Les sources OFSP consultées ne donnent pas une prévalence unique de ce scénario chez les malades chroniques. La référence radon est300 Bq/m³en moyenne annuelle pour les locaux où des personnes séjournent régulièrement. La valeur1 000 Bq/m³concerne les postes exposés au radon et ne remplace pas la référence générale de tous les lieux de travail.',
 mechanism=[('Une exposition intérieure peut varier selon la pièce et les activités.','L’histoire compare lieux, horaires, occupants concernés et événements récents.','Le bilan médical et l’enquête sur le bâtiment sont menés sans conclusion prématurée.'),('L’humidité peut signaler un problème persistant du bâtiment.','L’évaluation décrit signes visibles et cause probable avec les professionnels compétents.','La correction traite l’humidité et ses conséquences plutôt que le seul aspect visible.'),('La concentration de radon varie et nécessite un protocole représentatif.','Le service agréé organise une mesure selon la durée et les pièces requises.','Une mesure courte estime un risque de dépassement mais ne constitue pas une moyenne annuelle agréée.')],
 diff=[('Une maladie aiguë ou une décompensation reste possible.','Le médecin examine les symptômes et la gravité actuelle.','Le soin nécessaire n’attend pas les résultats d’une enquête du logement.','Une pièce humide ne prouve pas la cause de toute dyspnée.'),('Une exposition intérieure ciblée peut contribuer aux symptômes.','L’entretien cherche une relation temporelle et spatiale cohérente.','L’enquête recherche une source plausible et les mesures utiles.','Une amélioration hors du bâtiment reste un argument, pas une preuve mécanistique complète.'),('Le radon demande une démarche distincte du symptôme irritatif.','Le résultat est interprété selon protocole, durée et locaux mesurés.','Le risque à long terme et l’assainissement sont discutés avec les spécialistes.','Une mesure courte ne diagnostique pas la cause d’une irritation actuelle.'),('Une recherche non ciblée de polluants peut être peu informative.','Le bilan commence par symptômes, contexte et examen du bâtiment.','Les mesures choisies répondent à une question définie par le spécialiste.','Un panel coûteux ne garantit pas une explication ni une correction utile.')],
 ask=[('Quels symptômes concernent quelles personnes et dans quelles pièces?','La distribution aide à formuler une hypothèse d’exposition.','Le médecin conserve aussi les diagnostics individuels possibles.'),('Les symptômes varient-ils lors des séjours hors du bâtiment?','La temporalité contribue au raisonnement sans suffire à prouver la cause.','Le bilan documente les variations et les autres changements concomitants.'),('Voyez-vous humidité, moisissures, dégâts ou sources de fumée?','La description oriente les démarches techniques et les premières corrections.','Les dégâts sont signalés au responsable du bâtiment selon la démarche OFSP.'),('Comment la mesure de radon a-t-elle été réalisée?','Durée, saison, pièces et service déterminent la portée du résultat.','Une donnée courte n’est pas présentée comme un contrôle annuel agréé.')],
 exam=[('L’état respiratoire correspond à la référence habituelle.','Le médecin examine les symptômes actuels et les signes de décompensation selon la maladie.','Une aggravation clinique suit son parcours sans attendre une mesure environnementale.'),('Le bilan décrit des faits reproductibles du logement.','L’occupant et le professionnel identifient pièces, dates, travaux et dégâts observés.','Une impression d’odeur ou une photographie seule ne caractérise pas tout le risque.'),('La mesure respecte le protocole annoncé.','Le spécialiste vérifie service agréé, durée et localisation des dosimètres.','Un résultat non conforme est conservé avec sa limite plutôt que transformé en moyenne annuelle.')],
 syndromes=[('Le profil de symptômes liés au lieu repose sur une hypothèse documentée.','La personne décrit des symptômes qui varient avec les séjours.','Le médecin recherche le retentissement clinique et les autres causes.','Le spécialiste choisit une investigation du bâtiment utile à la décision.'),('Le profil de risque radon relève d’une exposition à long terme.','La personne peut ne présenter aucun symptôme spécifique.','La mesure agréée fournit une information sur la concentration, pas un examen clinique individuel.','Le résultat oriente la correction du bâtiment et son contrôle.')],
 criteria='Le diagnostic médical et le constat environnemental restent distincts. La mesure agréée du radon demande au moins 90 jours pendant octobre–mars; une année est recommandée et au moins deux pièces régulièrement occupées sont mesurées. La mesure courte non agréée estime la probabilité d’un dépassement mais n’est pas la moyenne annuelle. L’OFSP recommande d’abord un bilan général avant des analyses de substances précipitées.',
 tests=[('Le bilan médical évalue les troubles réels.','Le médecin décrit symptômes, gravité, maladies et chronologie.','Un examen normal à un instant ne démontre pas l’absence de toute exposition.','La conduite reste liée au besoin clinique et aux hypothèses plausibles.'),('L’enquête du logement est structurée.','Les occupants décrivent pièces, ventilation, dégâts, travaux et sources possibles.','Une association temporelle ne suffit pas à nommer une substance responsable.','Le spécialiste définit les questions techniques utiles.'),('La mesure radon agréée suit un protocole.','Le service agréé dispose les dosimètres dans les locaux prévus et respecte la durée.','La valeur est reliée à sa période et à la référence300 Bq/m³.','Le résultat et les suites sont discutés avec les interlocuteurs compétents.'),('L’investigation technique approfondie suit une question persistante.','Le spécialiste visite le site avant de choisir les analyses nécessaires.','Un résultat isolé ou un panel non ciblé peut rester peu interprétable.','La correction proposée répond à une source identifiée ou à une hypothèse documentée.')],
 urgent=['Le médecin évalue d’abord l’état des occupants symptomatiques et la gravité actuelle. Il n’attend pas le résultat d’une mesure radon longue pour traiter une décompensation.','La réduction d’une exposition suspecte est envisagée si elle est faisable en sécurité, sans présenter une cause non prouvée comme certaine. Le niveau de soins suit l’état clinique.','Les dégâts d’humidité et moisissures sont signalés rapidement par écrit à la gérance ou au propriétaire selon la démarche OFSP. La recherche de la cause et la correction du bâtiment sont organisées.','Le suivi distingue évolution des symptômes, correction technique et contrôle radon si nécessaire. Aucun résultat de bâtiment n’est présenté comme un certificat de guérison médicale.'],
 care=[('Le but clinique est de traiter les symptômes et la maladie identifiée.','Le médecin garde les diagnostics associés et le suivi approprié.','Une correction du logement ne remplace pas les soins nécessaires.'),('Le but technique est une correction ciblée.','L’OFSP recommande de rechercher la source et de faire intervenir un spécialiste plutôt que des analyses précipitées.','La simple disparition visuelle d’une moisissure ne résout pas forcément sa cause.'),('La démarche radon utilise un service agréé.','La mesure et l’assainissement sont distingués et les suites sont clarifiées avec les autorités ou spécialistes compétents.','La valeur de référence ne devient pas un diagnostic individuel de maladie.'),('Le soutien social prend en compte la faisabilité.','La personne peut avoir besoin d’aide pour les courriers, le contact avec la gérance ou les solutions temporaires.','Une recommandation de déménagement sans solution accessible ne règle pas le problème.')],
 follow=[('Les symptômes sont suivis dans leur évolution.','Le médecin compare état clinique et changements de conditions de vie.','Une absence d’amélioration conduit à reprendre les hypothèses.'),('Les corrections sont vérifiées avec le professionnel compétent.','Le responsable confirme ce qui a été fait et ce qui reste à traiter.','Une facture ou une promesse de travaux ne prouve pas la correction.'),('Le contrôle radon respecte la définition de mesure applicable.','Le spécialiste précise le protocole et l’interprétation du résultat.','Une valeur courte rassurante ne remplace pas automatiquement le contrôle prévu.')],
 pitfalls=[('Un appareil a mesuré deux jours de radon.','Le candidat explicite la portée courte non agréée et organise la démarche adaptée.','Ce résultat n’est pas une moyenne annuelle.'),('La famille attribue une irritation immédiate au radon.','Le médecin distingue symptômes actuels, enquête intérieure et risque à long terme.','Une concentration ne démontre pas cette causalité individuelle.'),('La gérance repeint une tache sans rechercher l’humidité.','Le suivi vérifie la cause et la correction technique.','Un aspect propre ne garantit pas une source supprimée.')]
),
10: dict(
 refs=['S18','S17','S24','S28','S02','S07'],
 focus='La transition est un processus préparant la continuité des soins et la participation du jeune; le transfert est un changement de service. L’âge civil, le discernement pour un soin et l’aptitude pratique à organiser le suivi constituent des dimensions différentes.',
 case='Un adolescent de 17 ans connaît son traitement mais ses parents organisent les rendez-vous et répondent à toutes les questions. L’équipe pédiatrique prévoit un transfert; aucun rendez-vous adulte n’est confirmé et le jeune souhaite parler seul d’une difficulté de prise.',
 epi='La page CHUV de transition rhumatologique, mise à jour en 2019, décrit un parcours local en plusieurs étapes. Ses tranches d’âge et durées ne constituent pas une règle fédérale applicable à toutes les maladies. Aucune fréquence suisse globale de rupture de transition n’a été trouvée dans les sources consultées.',
 mechanism=[('Le changement d’équipe peut interrompre des habitudes de suivi.','Le bilan vérifie le service destinataire, les documents et le rendez-vous réel.','Un relais nominatif et accepté sécurise la continuité.'),('L’autonomie pratique se développe progressivement.','Le jeune montre ce qu’il sait et ce qu’il souhaite encore partager.','L’apprentissage est gradué avec un soutien adapté.'),('La place familiale peut soutenir ou limiter la parole personnelle.','Le médecin propose un temps propre et clarifie les informations partagées.','La décision respecte le discernement et le secret dans le cadre légal applicable.')],
 diff=[('Une rupture de soin imminente peut exposer à une aggravation.','L’équipe vérifie traitements disponibles et prochain contact confirmé.','Un relais est organisé avant une interruption prévisible.','Une lettre envoyée ne garantit pas un rendez-vous obtenu.'),('Une difficulté d’apprentissage diffère d’un refus informé.','Le médecin demande au jeune de montrer son plan et ses préférences.','Le soutien cible le besoin réel sans retirer la parole personnelle.','Un parent organisateur ne prouve pas une incapacité du jeune.'),('Une question de discernement exige une appréciation propre.','Le médecin examine la décision précise et les capacités dans des conditions adaptées.','Il applique le cadre légal des droits strictement personnels et de représentation si nécessaire.','La minorité ne vaut pas incapacité automatique.'),('Une souffrance psychique ou un obstacle matériel peut expliquer des rendez-vous manqués.','L’entretien explore humeur, langue, coût, transport et relation aux soins.','La réponse associe les relais nécessaires.','Le terme non-adhésion ne remplace pas le raisonnement.')],
 ask=[('Qu’aimerais-tu décider toi-même et pour quoi souhaites-tu encore de l’aide?','La question précise une autonomie choisie plutôt qu’un retrait brutal des proches.','Le médecin répartit les responsabilités avec le jeune.'),('Peux-tu expliquer ton traitement et ce que tu ferais en cas de problème?','La démonstration explore la compétence pratique et les besoins d’apprentissage.','Le professionnel reprend les éléments nécessaires et vérifie de nouveau.'),('Qui te recevra ensuite et quand le rendez-vous est-il confirmé?','La continuité demande un interlocuteur réel et une échéance obtenue.','L’équipe garde une responsabilité de relais tant que le passage reste incertain.'),('Quelles informations acceptes-tu de partager avec tes proches?','La confidentialité et les préférences doivent être explicites.','Le médecin clarifie le cadre selon le discernement, la décision et les règles applicables.')],
 exam=[('Le jeune peut exposer sa situation dans un échange adapté.','Le médecin observe compréhension, raisonnement et expression du choix pour la décision concernée.','Une hésitation demande un soutien et une appréciation, pas une incapacité automatique.'),('La maladie est stable selon les critères de son suivi.','L’équipe reprend les éléments cliniques utiles à la continuité.','Une aggravation est traitée sans attendre l’achèvement administratif du transfert.'),('Le plan pratique peut être utilisé par le jeune et ses appuis.','Le professionnel demande une démonstration des étapes et vérifie les contacts.','Une connaissance théorique du traitement ne prouve pas que le parcours est organisé.')],
 syndromes=[('Le profil de vulnérabilité de transition associe parcours et apprentissage.','Le jeune décrit incertitude sur les contacts ou besoin d’aide.','Le bilan vérifie les documents, les rendez-vous et l’utilisation du plan.','La préparation améliore la continuité plutôt que d’imposer un âge unique.'),('Le profil de décision personnelle concerne un soin précis.','Le jeune exprime un souhait qui peut différer de celui des proches.','Le médecin apprécie les capacités nécessaires et adapte l’information.','La responsabilité pratique et le droit de décider ne se confondent pas.')],
 criteria='Le processus est opérationnel quand une équipe destinataire accepte le relais, les informations utiles et le rendez-vous sont vérifiés, et le jeune sait comment demander de l’aide. Cette grille pédagogique n’est pas un score validé. Le discernement est apprécié pour l’acte précis selon l’ASSM et l’article16CC; l’article19cCC éclaire les droits strictement personnels du mineur capable de discernement.',
 tests=[('Le bilan de transition décrit le parcours.','Les équipes vérifient destinataire, documents utiles et rendez-vous confirmé.','Un dossier envoyé sans acceptation laisse le relais incertain.','La responsabilité de l’intervalle est clarifiée.'),('La démonstration du plan explore les compétences pratiques.','Le jeune explique les prises, les contacts et la réponse à un problème selon sa maladie.','Une erreur désigne un besoin d’apprentissage.','Le professionnel reprend le point et vérifie l’application.'),('L’appréciation du discernement concerne une décision précise.','Le médecin adapte l’information et examine les capacités dans les conditions de l’entretien.','La minorité ou une dépendance aux parents ne donnent pas seules la conclusion.','Les règles de consentement et de représentation suivent cette appréciation.'),('Un avis interdisciplinaire clarifie une difficulté persistante.','Les professionnels partagent les données nécessaires dans le cadre autorisé.','Les besoins psychiques, sociaux ou linguistiques peuvent coexister.','Le plan attribue un responsable pour chaque obstacle restant.')],
 urgent=['Le médecin identifie une interruption de soin ou une aggravation qui ne peut pas attendre le transfert. Les soins nécessaires et le contact de recours sont organisés immédiatement selon l’état.','Il vérifie les traitements effectivement disponibles et le professionnel responsable pendant l’intervalle. Il ne suppose pas que l’équipe adulte a accepté le dossier parce qu’un courrier a été envoyé.','Il donne au jeune un espace de parole adapté et clarifie le consentement aux échanges. Si le discernement manque et qu’un soin urgent est nécessaire, le cadre légal est appliqué sans retard évitable.','La transmission finale précise maladie, plan actuel, besoins d’aide, risques, rendez-vous et interlocuteur. Le jeune sait qui contacter avant la première consultation adulte.'],
 care=[('Le but est une continuité effective et une participation progressive.','Le plan distingue les tâches que le jeune réalise et celles qu’il partage encore.','La réussite ne se réduit pas à la date anniversaire.'),('La rencontre de la nouvelle équipe peut soutenir le passage.','L’exemple CHUV organise des consultations communes en rhumatologie; le parcours local est adapté à la maladie et aux ressources.','Les âges du service ne deviennent pas une obligation nationale.'),('Les proches participent dans le cadre convenu.','Le médecin clarifie le souhait du jeune, le discernement et les informations autorisées.','L’autonomie ne signifie pas un retrait imposé de toute aide familiale.'),('La continuité médicamenteuse est vérifiée sans inventer une prescription.','La liste actuelle, les renouvellements et le responsable sont confirmés.','Les doses et adaptations exigent l’information professionnelle propre à chaque traitement.')],
 follow=[('Le premier contact adulte est confirmé puis réalisé.','L’équipe vérifie ce qui s’est effectivement passé.','Une absence de consultation laisse un besoin de relais à résoudre.'),('Les compétences sont revues lors de chaque changement significatif.','Le jeune montre comment il utilise le plan et appelle de l’aide.','Une autonomie acquise dans une tâche ne prouve pas toutes les autres.'),('Le cadre de partage des informations est réexaminé.','Le médecin redemande les préférences et apprécie la décision concernée.','Un accord ancien ne devient pas une autorisation illimitée de tout transmettre.')],
 pitfalls=[('Le patient a 18 ans et le transfert est réputé réussi.','Le candidat vérifie le rendez-vous, les traitements et le contact réel.','La majorité ne prouve pas la continuité.'),('Les parents exigent automatiquement le contenu de l’entretien.','Le médecin vérifie le discernement, les droits personnels et le cadre de communication.','La parenté ne suffit pas à conclure sur toute information.'),('Le jeune connaît les noms des traitements mais aucun renouvellement n’est prévu.','L’équipe vérifie les prises réelles, la disponibilité et le responsable.','La connaissance théorique ne garantit pas l’accès.')]
)
})
